package vn.rtr.aeris.native94;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.nio.channels.*;import java.io.*;import java.util.*;
public final class DraftStoreTest {
 static int checks=0;static byte[] b(String x){return x.getBytes(StandardCharsets.UTF_8);}static void ok(String n,boolean v){if(!v)throw new AssertionError(n);System.out.println("PASS "+n);checks++;}interface Job{void run()throws Exception;}static void no(String n,Job f)throws Exception{boolean v=false;try{f.run();}catch(Exception e){v=true;}ok(n,v);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);Files.createDirectories(root);DraftStore s=new DraftStore(root.resolve("normal"));ok("empty draft no authority",s.load()==null);DraftStore.Snapshot a=s.save("ROOT",b("{\"draft\":1}"));ok("revision1 body SHA",a.revision==1&&a.sha.equals(DraftStore.hash(a.bytes)));ok("restart exact committed bytes",Arrays.equals(new DraftStore(root.resolve("normal")).load().bytes,a.bytes));ok("identical save no revision",s.save(a.token,a.bytes).token.equals(a.token));no("stale process refuses overwrite",()->s.save("ROOT",b("stale")));DraftStore.Snapshot z=s.save(a.token,b("{\"draft\":2}"));ok("revision2 previous digest",z.revision==2&&z.previous.equals(a.token));ok("historical record retained",Files.list(root.resolve("normal")).filter(p->p.toString().endsWith(".bin")).count()==2);no("oversize refused",()->s.save(z.token,new byte[DraftStore.MAX_BODY+1]));no("unknown head token",()->s.save("../head",b("bad")));
 try(FileChannel c=FileChannel.open(root.resolve("normal/LOCK"),StandardOpenOption.WRITE);FileLock l=c.lock()){no("concurrent writer file lock",()->new DraftStore(root.resolve("normal")).save(z.token,b("busy")));}
 for(String phase:new String[]{"RECORD_PUBLISHED","HEAD_PENDING","HEAD_COMMITTED"}){Path dir=root.resolve(phase);DraftStore clean=new DraftStore(dir);DraftStore.Snapshot first=clean.save("ROOT",b("old"));DraftStore faulty=new DraftStore(dir,p->{if(p.equals(phase))throw new IOException("Injected crash point");});no("fault surfaces "+phase,()->faulty.save(first.token,b("new")));DraftStore restarted=new DraftStore(dir);DraftStore.Snapshot last=restarted.load();ok("restart committed state "+phase,new String(last.bytes,StandardCharsets.UTF_8).equals(phase.equals("HEAD_COMMITTED")?"new":"old"));ok("failed revision preserved "+phase,Files.list(dir).filter(p->p.toString().endsWith(".bin")).count()==2);if(phase.equals("HEAD_PENDING")){ok("pending head disclosed",restarted.pending());no("pending prevents automatic publish",()->restarted.save(last.token,b("retry")));}else{DraftStore.Snapshot next=restarted.save(last.token,b("third"));ok("orphan sequence never reused "+phase,next.revision==3&&next.previous.equals(last.token));}}
 Path bad=root.resolve("tamper");DraftStore corrupt=new DraftStore(bad);DraftStore.Snapshot one=corrupt.save("ROOT",b("intact"));Path file=Files.list(bad).filter(p->p.toString().endsWith(".bin")).findFirst().get();Files.write(file,b("corrupt"));no("corrupt record blocks load",()->new DraftStore(bad).load());ok("corruption retained",Files.exists(file));no("corrupt store blocks save",()->corrupt.save(one.token,b("new")));
 Path missing=root.resolve("missing");DraftStore m=new DraftStore(missing);DraftStore.Snapshot m1=m.save("ROOT",b("1"));m.save(m1.token,b("2"));Path old=Files.list(missing).filter(p->p.toString().contains(m1.token)).findFirst().get();Files.delete(old);no("missing historical parent cannot fake intact",()->m.load());
 Path sym=root.resolve("link");Files.createSymbolicLink(sym,root.resolve("normal"));no("symlink root refused",()->new DraftStore(sym));Path symHead=root.resolve("head-link");DraftStore hs=new DraftStore(symHead);Files.createSymbolicLink(symHead.resolve("HEAD"),root.resolve("normal/HEAD"));no("symlink head refused",()->hs.load());
 DraftStore quota=new DraftStore(root.resolve("quota"));String token="ROOT";for(int i=0;i<DraftStore.MAX_RECORDS;i++)token=quota.save(token,b("r"+i)).token;final String finalToken=token;no("revision quota refuses without deleting",()->quota.save(finalToken,b("overflow")));ok("quota retains all bounded records",Files.list(root.resolve("quota")).filter(p->p.toString().endsWith(".bin")).count()==DraftStore.MAX_RECORDS);System.out.println("TOTAL "+checks+" PASS; opaque draft journal only, no authority restored");}
}
